sudo install -d -m 0755 /var/www/https-8443
sudo tee /var/www/https-8443/index.html >/dev/null <<'ANTRIEB_HTML'
HTTPS service on node1
ANTRIEB_HTML
sudo tee /etc/nginx/sites-available/https-8443 >/dev/null <<'ANTRIEB_NGINX'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name _;

    ssl_certificate     /etc/nginx/tls/server.crt;
    ssl_certificate_key /etc/nginx/tls/server.key;
    ssl_protocols TLSv1.2 TLSv1.3;

    root /var/www/https-8443;
    location / {
        try_files $uri $uri/ =404;
    }
}
ANTRIEB_NGINX
sudo ln -sfn /etc/nginx/sites-available/https-8443 /etc/nginx/sites-enabled/https-8443
sudo rm -f /etc/nginx/sites-enabled/default
sudo nginx -t
sudo systemctl reload nginx
systemctl is-active nginx
ss -tlnp | grep ':8443 ' 
curl --fail --silent --show-error --cacert /etc/nginx/tls/server.crt "https://$NODE_IP:8443/"
